record.field:
# Trouver le website de la company de l'utilisateur
user_website = env['website'].search([
    ('company_id', '=', env.user.company_id.id)
], limit=1)

if not user_website:
    # Si pas de website pour cette company, en créer un
    user_website = env['website'].create({
        'name': f'Site {env.user.company_id.name}',
        'company_id': env.user.company_id.id,
        'domain': '',
    })

# Rediriger vers l'action website avec le bon website_id en contexte
action = {
    'type': 'ir.actions.act_url',
    'url': f'/website/{user_website.id}',
    'target': 'self',
}
